node --input-type=module <<'NODE'
import { createRequire } from 'node:module'
import { readFileSync } from 'node:fs'
import { join } from 'node:path'
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright')
const require = createRequire(join(runtime, 'package.json'))
const { chromium } = require('playwright')
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'))
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim()
const browser = await chromium.launch({ ...config.browser.launchOptions })
const page = await browser.newPage({ viewport: { width: 1280, height: 900 } })
await page.goto('http://127.0.0.1:3002/', { waitUntil: 'networkidle' })
console.log('dimensions', await page.evaluate(() => ({ inner: [innerWidth,innerHeight], doc: [document.documentElement.scrollWidth,document.documentElement.scrollHeight], body: [document.body.scrollWidth,document.body.scrollHeight], canvas: [...document.querySelectorAll('canvas')].map(c=>[c.width,c.height,c.getBoundingClientRect().toJSON()]) })))
console.log('buttons', await page.locator('button').evaluateAll(bs => bs.map((b,i)=>({i,text:b.innerText.trim().replace(/\s+/g,' '),title:b.title,cls:b.className,disabled:b.disabled,rect:b.getBoundingClientRect().toJSON()}))))
await browser.close()
